dy list" id="taskList"></div></section><section class="panel"><div class="head"><h2>Training + certifications</h2></div><div class="body list" id="trainingList"></div></section><section class="panel"><div class="head"><h2>Recognition</h2></div><div class="body"><div class="list" id="recognitionList"></div><?php if($canRecognize):?><form class="form" id="recognitionForm" style="margin-top:12px"><input class="wide" name="title" placeholder="Recognition title" required><input name="recognitionType" value="manager_recognition" placeholder="Recognition type"><select name="visibility"><option value="employee_visible">Employee visible</option><option value="manager_private">Manager private</option></select><textarea class="wide" name="body" placeholder="What are you recognizing?" required></textarea><button class="btn dark" type="submit">Save recognition</button></form><?php endif;?></div></section><?php if($canManage):?><section class="panel"><div class="head"><h2>Private coaching notes</h2><span class="muted">Manager only</span></div><div class="body"><div class="list" id="noteList"></div><form class="form" id="noteForm" style="margin-top:12px"><input class="wide" name="title" placeholder="Coaching note title" required><select name="noteType"><option value="coaching">Coaching</option><option value="one_on_one">1:1</option><option value="training_followup">Training follow-up</option><option value="manager_observation">Manager observation</option></select><input name="occurredAt" type="datetime-local"><textarea class="wide" name="body" placeholder="Private manager note" required></textarea><button class="btn dark" type="submit">Save private note</button></form></div></section><section class="panel"><div class="head"><h2>Development goals</h2><span class="muted">Manager-authored</span></div><div class="body"><div class="list" id="goalList"></div><form class="form" id="goalForm" style="margin-top:12px"><input class="wide" name="title" placeholder="Development goal" required>